import json,shutil,xml.etree.ElementTree as ET
from pathlib import Path
from experiment import sha
def read(p):return json.loads(Path(p).read_text(encoding='utf8'))
def main():
    run=read('runs/neral50m_pilot_a/run.json');summary=read('runs/neral50m_pilot_a/summary.json');throughput=read('reports/throughput50.json');old=read('reports/throughput50_unpadded.json');before=read('reports/free50_baseline20.json');after=read('reports/free50_pilot_a.json')
    indices=list(range(5))+list(range(10,15));scores20=[1,2,2,2,0,1,4,1,4,1];scores50=[1]*10
    ratings=[{'id':before['responses'][i]['id'],'score20':a,'score50':b} for i,a,b in zip(indices,scores20,scores50)]
    manual={'reviewer':'Codex agent qualitative reading, no external judge API','rubric':'0 unintelligible; 1 isolated words/no usable statement; 2 partially understandable; 3 mostly relevant understandable; 4 clear correct natural','subset':'First five German and first five English chat prompts; retrospective pilot reading. All 100 raw outputs retained.','ratings':ratings,'mean20':sum(scores20)/10,'mean50':sum(scores50)/10,'promotion':False}
    Path('reports/manual_free50.json').write_text(json.dumps(manual,indent=2))
    tests=sum(int(s.attrib.get('tests',0)) for s in ET.parse('reports/pytest_50.xml').iter('testsuite'))
    m=throughput['selected'];ratio=m['tokens_per_second']/old['selected']['tokens_per_second']
    lines=['# Neral-50M: Sprachpilot A','', '**Status: Pretraining-Experiment, kein fertiger Chatbot.** Der bestehende 20M-Stand bleibt Standard. Kein fremdes Sprachmodell wurde geladen oder zur Laufzeit aufgerufen.', '', '## Modell und Daten','- Exakt **50.012.976 trainierbare Parameter**; acht Blöcke, d_model 624, zwölf Heads mit Dimension 52, SwiGLU 2496, 260 Byte-Token, Kontextlimit 4096.', '- Neu und lokal initialisierte eigene Neral-Architektur, Seed 50013. Der schlechtere 40M-Versuch wurde nicht als Ausgangspunkt verwendet.', '- 5.000 Wikipedia-Artikel geladen, 4.120 behalten. Training: 3.736 Artikel, 21.915.506 Tokens einschließlich BOS/EOS. Herkunft, Lizenz, Filter und dokumentweise Splits siehe DATA_PROVENANCE.md.', '- Separates neues Test- und Holdout-Material blieb unbenutzt. Der Pilot nutzt etwa 4,56 % des vorbereiteten Trainings-Tokenumfangs; zufällige Fenster können sich überlappen, dies ist keine behauptete Zahl einzigartig gelernter Tokens.', '', '## Effizienz tatsächlich gemessen', f'- Neun Batch-/Sequenzkombinationen vor und nach der Optimierung gemessen. Beste Konfiguration: Sequenz {m["seq"]}, Micro-Batch {m["batch"]}, {m["tokens_per_step"]} Tokens pro Update.', f'- Bester gemessener Durchsatz: {old["selected"]["tokens_per_second"]:,.0f} → {m["tokens_per_second"]:,.0f} Tokens/s ({(ratio-1)*100:.1f} % mehr). Kurze Messungen mit drei gewerteten Schritten nach Warmup, keine langfristige Leistungszusage.', '- Ursache: Flash Attention ist im installierten Windows-PyTorch nicht eingebaut. Der effiziente CUDA-SDPA-Kernel verlangt durch acht teilbare Head-Dimensionen. Parameterloses Null-Padding 52 → 56, Skala weiterhin 1/√52, anschließend Abschneiden der vier Zusatzdimensionen aktiviert den effizienteren Kernel. CPU-FP32-Vergleich identisch auf dem dokumentierten Prüftensor.', '- uint16-Memmap, vorberechnete Byte-Token, zusammengepackte Dokumente mit BOS/EOS, 0 Padding-Tokens, BF16, fused AdamW. Dokumentübergreifende Attention ist möglich und nicht isoliert.', '- Größte Batch ist nicht automatisch schneller. Der unoptimierte 1024×16-Fall belegte über 14 GB PyTorch-Speicher und fiel auf rund 3.358 Tokens/s; auf Windows trat kein CUDA-OOM auf, Speicherüberschreitung/Paging ist eine plausible Erklärung. Diese Kombination wurde nicht gewählt.', '- torch.compile, pinned memory und Gradient Checkpointing wurden nicht als schneller behauptet oder aktiviert; keine Messung dieser optionalen Varianten.', '', '## Ausgeführter Pilot', f'- Verarbeitete Tokens: **{summary["processed_tokens"]:,}**, {summary["steps"]} Updates. Tatsächliche Trainingsschleife inklusive Evaluation/Schreiben: **{summary["elapsed_seconds"]:.2f} Sekunden**.', f'- Davon Update-Berechnung: {summary["optimizer_seconds"]:.2f} Sekunden, {summary["optimizer_tokens_per_second"]:,.0f} Tokens/s. Deutsch {summary["language_tokens"]["de"]:,}, Englisch {summary["language_tokens"]["en"]:,}.', f'- Peak allocated {summary["peak_allocated"]/2**30:.2f} GiB, reserved {summary["peak_reserved"]/2**30:.2f} GiB; GPU: RTX 4070. Dies ist PyTorch-Speicher, kein vollständiger Systemverbrauch.', f'- Feste Validation-Slices: Loss **{run["baseline"]["macro"]:.4f} → {summary["best_validation"]:.4f}**. Best-validation-Checkpoint bei Schritt 122. Das ist keine Auswahl als bester Chatbot.', '- Pretraining wurde gemäß Tokenbudget beendet. Keine weitere Skalierung und kein Instruction-Tuning nach dem fehlgeschlagenen freien Sprachtest.', '', '## Freie Generierung: wichtiger als der Loss','100 vorher eingefrorene Prompts, gleiche Eingaben, greedy, maximal 64 Byte-Token; rohe Ausgaben und Token-IDs unverändert gespeichert. Dieses kurze Antwortbudget begrenzt die Aussagekraft über mittellange Antworten. Zusätzliche 20 Holdout-Prompts wurden nicht ausgeführt.','', '| Messung | Neral-20M Preview 02 | 50M Pilot A |','|---|---:|---:|']
    for key,label in [('valid_utf8_fraction','Valides UTF-8'),('eos_fraction','EOS-Abschluss'),('mean_repeated_trigram_fraction','Wiederholte Wort-Trigramme')]:lines.append(f'| {label} | {before["summary"][key]:.2%} | {after["summary"][key]:.2%} |')
    lines += [f'| Rechenantwort exakt | {before["summary"]["numeric_exact"]}/10 | {after["summary"]["numeric_exact"]}/10 |',f'| Verständlichkeit, manuelle Stichprobe 0–4 | {manual["mean20"]:.1f} | {manual["mean50"]:.1f} |','', 'Manuelle Stichprobe: erste fünf deutsche und erste fünf englische Chatfragen, nachträgliche Bewertung durch den Codex-Agenten; kein unabhängiges menschliches Gutachten. Sprachkonsistenz wird nur durch eine kleine Stopwort-Heuristik diagnostiziert. Codeantworten wurden gespeichert, aber nicht auf dem Host ausgeführt; kein funktionaler Coding-Score.', '', '**Der 50M-Pilot besteht das Qualitätsgate nicht.** Er produziert insbesondere „der der der …“ und beendet keine der 100 Antworten innerhalb des Budgets mit EOS. Die Verständlichkeit verschlechtert sich gegenüber dem ohnehin schwachen 20M-Stand. Es gibt daher keinen `best_free_generation`-Checkpoint und keine automatische Ablösung des Standards.', '', '## Laufzeitprojektion aus gemessenem Durchsatz','Nur reine Trainings-Token-Verarbeitung, ohne zusätzliche Datenbeschaffung, Evaluation, Checkpoints oder Hardwarekosten:', '']
    lines += [f'- {int(n)/1e6:g} Mio. Tokens: etwa {h:.2f} Stunden.' for n,h in throughput['training_only_estimated_hours'].items()]
    lines += ['', 'Stromverbrauch und Euro-/Tokenkosten sind nicht berechnet: keine integrierte Leistungsmessung und kein Nutzer-Stromtarif vorhanden.', '', '## Veröffentlichung und nächste Schritte',f'{tests} lokale Tests bestanden; bestehende Security- und Helios-Features bleiben erhalten. Reproduktions- und Fortsetzungsbefehle stehen in REPRODUCE.md. Die Fortsetzung ist vorbereitet, wurde nach dem fehlgeschlagenen freien Sprachgate aber nicht automatisch gestartet.', '', 'Privates Repository: https://github.com/Cola968/neral-helios. Quellcode, Dokumentation, Tests und ausgewählte Messberichte werden übertragen. Rohtrainingsdaten, lokale Projekt-Datenbank, Chats, virtuelle Umgebung und vollständige Optimizer-Checkpoints bleiben lokal. Kompakte eigene Modellgewichte werden gegebenenfalls getrennt als private Release-Dateien bereitgestellt.', '', 'Der nächste Entwicklungsbedarf ist eine längere, sorgsam beobachtete allgemeine Sprachlernphase auf breiterem Material und eine belastbarere Generationsbewertung. Ein Nutzer-fähiger 50M-Chatbot wurde mit diesem Pilot nicht erreicht.']
    Path('PREVIEW_50M.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
    Path('MODEL_CARD.md').write_text('# Neral family model card\n\nOwn local decoder-only byte-level language models. No external learned weights, LoRAs or cloud inference.\n\n| Model | Parameters | Status |\n|---|---:|---|\n| Neral Preview 02 | 20,587,008 | Current default; free language frequently incoherent |\n| Neral 40M capacity experiment | 40,051,200 | Validation regressed; historical optional experiment |\n| Neral 50M pilot A | 50,012,976 | New random initialization, 999,424 language-pretraining tokens; free-language gate failed |\n\nArchitecture, evaluation, performance, limitations and actual training: [PREVIEW_50M.md](PREVIEW_50M.md). Data: [DATA_PROVENANCE.md](DATA_PROVENANCE.md). Reproduction: [REPRODUCE.md](REPRODUCE.md).\n\n## Limitations\n\nNot reliable for general advice, coding, math or autonomous decisions. Local deterministic SOLVE/project tools are separate software capabilities, not model intelligence. The prompt guard is heuristic. New natural-language corpus is Wikipedia only, not enough for a general assistant. Historical 20M corpus provenance is incomplete. No commercial/public-readiness claim or new blanket model license is made.\n\n## Artifacts\n\n50M inference SHA-256: `'+sha('export/neral50m/neral50m.pt')+'`.\n\n20M Preview 02 inference SHA-256: `'+sha('export/pilot_02/neral20m.pt')+'`.\n\nFull optimizer/RNG checkpoints remain local. Both train and validation source hashes are recorded in run metadata.\n',encoding='utf8')
    Path('TRAINING_LOG.md').write_text('# Measured training log\n\nSee PREVIEW_02.md for the first 20M pilot and PREVIEW_03.md for the two 40M experiments. Those historical artifacts remain unchanged.\n\nLatest own 50M pilot: [PREVIEW_50M.md](PREVIEW_50M.md). The run consumed '+str(summary['processed_tokens'])+' tokens in '+str(round(summary['elapsed_seconds'],2))+' seconds. No larger run or chat finetuning was launched. Lower validation loss did not pass free-generation quality gates.\n',encoding='utf8')
    print(json.dumps({'manual':manual,'tests':tests,'throughput_improvement':ratio-1},indent=2))
if __name__=='__main__':main()
